//! @generated by xtask split-cards.
use super::prelude::*;

/// Hidden Daggers. Cost 1, Skill. Discard exactly `min(2, hand)` cards,
/// then spawn 2 Shivs into hand. C# `HiddenDaggers.OnPlay`
/// (`HiddenDaggers.cs:31`): `CardSelectCmd.FromHandForDiscard`
/// `prefs(Cards=2)` (single-arg `CardSelectorPrefs` ⇒ `min == max == 2`,
/// so discard exactly 2 — capped by hand size) → `CardCmd.Discard`, then
/// `Shiv.CreateInHand(Shivs=2)`.
///
/// The discard is a **player choice**, not an RNG draw — bead
/// `sts2-rs-1xmxp` replaces the prior uniform-random `state.rng` subset
/// (the `NOTE(sts2-rs-sr3ql)` legacy-rng caveat is now resolved). We
/// snapshot the hand *before* spawning Shivs so the new Shivs are never
/// offered as discard candidates; the end state (original hand − chosen
/// + 2 Shivs) is identical to C#'s discard-then-add ordering. When the
/// hand has `≤ 2` cards there is no real choice (all must go), so we
/// auto-discard without a prompt (FirstOrDefault precedent). The
/// start-of-turn Shiv listener is the `PowerKind::InfiniteBlades` arm in
/// `hooks.rs` (bead `sts2-rs-m4kb`).
pub(crate) fn play_hidden_daggers(
    state: &mut CombatState,
    _t: Option<CreatureUid>,
) -> EffectResult {
    // C# `HiddenDaggers.cs:OnPlay`: if `IsUpgraded`, the spawned Shivs are
    // upgraded (`CardCmd.Upgrade(item)` per spawn; Shiv+ deals 6).
    let shivs = sts2_core::PostChoiceEffect::SpawnInHand {
        card_id: CardId::Shiv,
        count: 2,
        upgraded: current_card_upgraded(state),
    };
    let original: smallvec::SmallVec<[sts2_core::CardUid; 16]> =
        state.player.hand.iter().copied().collect();
    let discard_count = original.len().min(2);
    if original.len() <= discard_count || sts2_core::combat_loop::combat_is_ending(state) {
        // No meaningful choice (must discard every hand card, or none):
        // auto-discard, matching the FromHandForDiscard auto-resolve. Route
        // through the Sly-aware discard so a discarded Sly card (Tactician →
        // +1 energy, Ricochet, Sneaky, Reflex, …) auto-plays — exactly as the
        // `DiscardFromHand` choice resolver does (lib.rs::resolve_discard_from_hand).
        // The prior raw `discard_hand_card` loop dropped the Sly trigger
        // (Silent fuzz seed 24: HiddenDaggers discarding Tactician left energy
        // at 0 vs C#'s 1).
        if sts2_core::combat_loop::combat_is_ending(state) {
            spawn_hidden_dagger_shivs(state, shivs);
        } else {
            let to_discard: smallvec::SmallVec<[sts2_core::CardUid; 16]> =
                original.iter().take(discard_count).copied().collect();
            // The Shivs wait behind every Sly auto-play, including a Sly
            // select the player answers first (GH #1131).
            let then = sts2_core::LoopThen::Call(
                spawn_hidden_dagger_shivs_packed,
                u32::from(current_card_upgraded(state)),
            );
            let _ =
                sts2_core::card_effects::discard_hand_cards_then(state, &to_discard, Some(then));
        }
    } else {
        // Pick exactly `discard_count` of the hand to discard. The
        // `sts2-rs-enwwr` multi-pick fan-out enumerates the selections;
        // the `DiscardFromHand` resolver discards each chosen card, then
        // spawns the Shivs from `post_effect`. They must wait for the pick:
        // a discarded Sly card (Reflex) auto-plays inside C#'s
        // `CardCmd.Discard`, so its draw lands in hand BEFORE the Shivs
        // (GH #1054, Silent-1001 act-3 `hand_costs` split).
        let options: Vec<sts2_core::ChoiceOption> = original
            .iter()
            .map(|&uid| {
                let idx = uid.0.get() as usize - 1;
                sts2_core::ChoiceOption {
                    card_id: state.cards[idx].card_id,
                    upgraded: state.cards[idx].upgraded,
                    card_uid: Some(uid),
                    source_pile: Some(sts2_core::cards::PileKind::Hand),
                }
            })
            .collect();
        let n = u8::try_from(discard_count).expect("min(2, _) fits u8");
        state.open_hand_choice(sts2_core::PendingChoice {
            kind: sts2_core::ChoiceKind::DiscardFromHand,
            options,
            min_select: n,
            max_select: n,
            can_skip: false,
            post_effect: Some(shivs),
            picked: smallvec::SmallVec::new(),
        });
    }
    EffectResult::Resolved
}

/// [`spawn_hidden_dagger_shivs`] as a Sly-loop follow-up; `upgraded` is 0 or 1.
fn spawn_hidden_dagger_shivs_packed(state: &mut CombatState, upgraded: u32) {
    let shivs = sts2_core::PostChoiceEffect::SpawnInHand {
        card_id: CardId::Shiv,
        count: 2,
        upgraded: upgraded != 0,
    };
    spawn_hidden_dagger_shivs(state, shivs);
}

/// Spawn HiddenDaggers' Shivs inline (no discard choice was opened).
fn spawn_hidden_dagger_shivs(state: &mut CombatState, shivs: sts2_core::PostChoiceEffect) {
    let sts2_core::PostChoiceEffect::SpawnInHand {
        count, upgraded, ..
    } = shivs
    else {
        return;
    };
    // The discard can down the last enemy (Tingsha); then `CardCmd.Upgrade`
    // is a no-op (`CombatManager.IsEnding`, CardCmd.cs:267-270, GH #1150).
    let upgraded = upgraded && !sts2_core::combat_loop::combat_is_ending(state);
    for _ in 0..count {
        let shiv_uid = spawn_shiv(state, PileKind::Hand);
        if upgraded {
            let idx = shiv_uid.0.get() as usize - 1;
            if let Some(card) = state.cards.get_mut(idx) {
                card.upgraded = true;
                card.base_damage = card.base_damage.saturating_add(2);
            }
        }
    }
}

